using ByteEngine.Core.Plugins;
using ByteEngine.Core.Variables;
using ByteEngine.Core.VisualLogic;
namespace KarlsonDemo.Plugin;
internal static class MiningEvents
{
 public static void Register(ByteEnginePluginContext c)
 {
  const string prefix="bytebard.karlsondemo.mining.";var target=new VisualArgumentDefinition("target","Mining operation",VariableValue.FromString("Self")){IsObjectReference=true};
  c.RegisterAction(new(){Id=prefix+"playEffect",Category="Mining",MenuGroup="Mining Effects",DisplayName="Play mining effect at object",Arguments=[new("target","Effect location",VariableValue.FromString("Self")){IsObjectReference=true},new("effect","Effect",VariableValue.FromString("MortarExplosion")){Choices=Enum.GetNames<MiningEffectCue>()},new("size","Size multiplier",VariableValue.FromNumber(1))],Execute=(i,e)=>{var location=WeaponEvents.ResolveObject(i,e);if(location!=null&&Enum.TryParse<MiningEffectCue>(EventValueResolver.GetString(i,"effect",e,"MortarExplosion"),out var cue))MiningEffects3D.Find(location)?.Emit(cue,location.Transform.WorldPosition,size:(float)EventValueResolver.GetNumber(i,"size",e));}});
  c.RegisterAction(new(){Id=prefix+"campMusicMix",Category="Mining",MenuGroup="Mining Audio",DisplayName="Set camp music volume",Arguments=[target,new("volume","Volume (0 to 1)",VariableValue.FromNumber(.38))],Execute=(i,e)=>{var audio=MiningAudio3D.Find(WeaponEvents.ResolveObject(i,e));if(audio!=null)audio.CampMusicVolume=Math.Clamp((float)EventValueResolver.GetNumber(i,"volume",e),0,1);}});
  c.RegisterAction(new(){Id=prefix+"explosionSize",Category="Mining",MenuGroup="Mining Effects",DisplayName="Set mine and mortar explosion sizes",Arguments=[target,new("mine","Mine size multiplier",VariableValue.FromNumber(1.8)),new("mortar","Mortar size multiplier",VariableValue.FromNumber(2.3))],Execute=(i,e)=>{var fx=MiningEffects3D.Find(WeaponEvents.ResolveObject(i,e));if(fx!=null){fx.MineExplosionScale=Math.Clamp((float)EventValueResolver.GetNumber(i,"mine",e),.05f,12);fx.MortarExplosionScale=Math.Clamp((float)EventValueResolver.GetNumber(i,"mortar",e),.05f,12);}}});
  c.RegisterAction(new(){Id=prefix+"defenceProjectileTuning",Category="Mining",MenuGroup="Company Defences",DisplayName="Set turret projectile speed and tracer",Arguments=[target,new("speed","Bullet speed",VariableValue.FromNumber(75)),new("length","Tracer length",VariableValue.FromNumber(2)),new("width","Tracer width",VariableValue.FromNumber(.035))],Execute=(i,e)=>{var defence=WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningDefense3D>();if(defence!=null){defence.ProjectileSpeed=(float)EventValueResolver.GetNumber(i,"speed",e);defence.TracerLength=(float)EventValueResolver.GetNumber(i,"length",e);defence.TracerWidth=(float)EventValueResolver.GetNumber(i,"width",e);}}});
  c.RegisterAction(new(){Id=prefix+"pauseGame",Category="Mining",MenuGroup="Pause and Settings",DisplayName="Pause game and open menu",Arguments=[target],Execute=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningPauseMenu3D>()?.Open()});
  c.RegisterAction(new(){Id=prefix+"resumeGame",Category="Mining",MenuGroup="Pause and Settings",DisplayName="Resume game and close pause menu",Arguments=[target],Execute=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningPauseMenu3D>()?.Resume()});
  c.RegisterCondition(new(){Id=prefix+"gamePaused",Category="Mining",MenuGroup="Pause and Settings",DisplayName="Game is paused",Arguments=[target],Evaluate=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningPauseMenu3D>()?.IsOpen==true});
  var spiderTarget=new VisualArgumentDefinition("target","Object with Animated Mining Spider",VariableValue.FromString("Self")){IsObjectReference=true};
  c.RegisterAction(new(){Id=prefix+"spiderExplosionReaction",Category="Mining",MenuGroup="Animated Mining Spider",DisplayName="Knock spider away from explosion",Arguments=[spiderTarget,new("origin","Explosion origin object",VariableValue.FromString("Self")){IsObjectReference=true},new("speed","Horizontal launch speed",VariableValue.FromNumber(7)),new("lift","Upward launch speed",VariableValue.FromNumber(3.5))],Execute=(i,e)=>{var spider=WeaponEvents.ResolveObject(i,e);var origin=WeaponEvents.ResolveObject(i,e,"origin");if(spider!=null&&origin!=null)spider.GetComponent<MiningSpiderAnimation3D>()?.ApplyExplosionImpact(spider.Transform.WorldPosition-origin.Transform.WorldPosition,(float)EventValueResolver.GetNumber(i,"speed",e),(float)EventValueResolver.GetNumber(i,"lift",e));}});
  c.RegisterCondition(new(){Id=prefix+"spiderKnockedDown",Category="Mining",MenuGroup="Animated Mining Spider",DisplayName="Spider is knocked down by an explosion",Arguments=[spiderTarget],Evaluate=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningSpiderAnimation3D>()?.IsBlastKnockedDown==true});
  c.RegisterAction(new(){Id=prefix+"spiderAnimation",Category="Mining",MenuGroup="Animated Mining Spider",DisplayName="Play spider animation",Arguments=[spiderTarget,new("clip","Animation suffix or full clip name",VariableValue.FromString("Jump")),new("loop","Loop animation",VariableValue.FromBoolean(false))],Execute=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningSpiderAnimation3D>()?.PlayClip(EventValueResolver.GetString(i,"clip",e,"Jump"),EventValueResolver.GetBoolean(i,"loop",e))});
  c.RegisterCondition(new(){Id=prefix+"spiderModelReady",Category="Mining",MenuGroup="Animated Mining Spider",DisplayName="Spider model and rig are ready",Arguments=[spiderTarget],Evaluate=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningSpiderAnimation3D>()?.ModelReady==true});
  c.RegisterCondition(new(){Id=prefix+"spiderAnimationState",Category="Mining",MenuGroup="Animated Mining Spider",DisplayName="Spider animation state is",Arguments=[spiderTarget,new("state","Animation state",VariableValue.FromString("Walk")){Choices=["Idle","Walk","Jump","Attack","Death","Explosion knockdown","Explosion ragdoll"]}],Evaluate=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningSpiderAnimation3D>()?.State==EventValueResolver.GetString(i,"state",e,"Walk")});
  MiningOperation3D? Op(VisualInstruction i,EventExecutionContext e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningOperation3D>();
  void A(string id,string name,Action<MiningOperation3D> run)=>c.RegisterAction(new(){Id=prefix+id,Category="Mining",MenuGroup="Mining Business",DisplayName=name,Arguments=[target],Execute=(i,e)=>{if(Op(i,e) is {} op)run(op);}});
  A("start","Start drilling or recover failed site",op=>{if(op.Phase==MiningPhase.Failed)op.Retry();else op.StartOperation();});A("refine","Refine one batch of ore",op=>op.BeginRefining());A("sell","Sell available raw and refined cargo",op=>op.SellCargo());
  foreach(var kind in Enum.GetValues<MiningUpgrade>()){var captured=kind;A("upgrade"+kind,"Buy "+kind+" upgrade",op=>op.Buy(captured));}
  A("save","Save company progress",op=>op.SaveProgress());
  var defenceTarget=new VisualArgumentDefinition("target","Company defence",VariableValue.FromString("Self")){IsObjectReference=true};
  c.RegisterAction(new(){Id=prefix+"defenceAnimation",Category="Mining",MenuGroup="Company Defences",DisplayName="Play defence animation",Arguments=[defenceTarget,new("clip","Clip suffix or full name",VariableValue.FromString("Deploy"))],Execute=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningDefense3D>()?.PlayVisual(EventValueResolver.GetString(i,"clip",e,"Deploy"))});
  c.RegisterCondition(new(){Id=prefix+"defenceModelReady",Category="Mining",MenuGroup="Company Defences",DisplayName="Animated defence model is ready",Arguments=[defenceTarget],Evaluate=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningDefense3D>()?.VisualReady==true});
  var ambushTarget=new VisualArgumentDefinition("target","Object with Curiosity Spider Ambush",VariableValue.FromString("Self")){IsObjectReference=true};
  foreach(string command in new[]{"activateAmbush","resetAmbush","cancelAmbush"}){string task=command;c.RegisterAction(new(){Id=prefix+task,Category="Mining",MenuGroup="Curiosity Spider Ambush",DisplayName=task=="activateAmbush"?"Release curiosity spider ambush":task=="resetAmbush"?"Rearm curiosity spider ambush":"Stop releasing ambush spiders",Arguments=[ambushTarget],Execute=(i,e)=>{if(WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningCuriosityAmbush3D>() is {} a){if(task=="activateAmbush")a.Activate();else if(task=="resetAmbush")a.Reset();else a.Cancel();}}});}
  foreach(string state in new[]{"ambushTriggered","ambushSpawning","insideAmbush"}){string flag=state;c.RegisterCondition(new(){Id=prefix+flag,Category="Mining",MenuGroup="Curiosity Spider Ambush",DisplayName=flag=="ambushTriggered"?"Curiosity ambush has been triggered":flag=="ambushSpawning"?"Curiosity ambush is releasing spiders":"Player is inside curiosity ambush area",Arguments=[ambushTarget],Evaluate=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningCuriosityAmbush3D>() is {} a&&(flag=="ambushTriggered"?a.Triggered:flag=="ambushSpawning"?a.Spawning:a.PlayerInside())});}
  var campTarget=new VisualArgumentDefinition("target","Player with Camp Arrangement",VariableValue.FromString("Self")){IsObjectReference=true};
  foreach(var task in new[]{"toggleCamp","finishCamp","confirmCampMove","cancelCampMove","rotateCampLeft","rotateCampRight"})
  {
   string name=task;c.RegisterAction(new(){Id=prefix+task,Category="Mining",MenuGroup="Camp Arrangement",DisplayName=task switch{"toggleCamp"=>"Open or close camp arrangement","finishCamp"=>"Finish arranging camp","confirmCampMove"=>"Confirm camp object placement","cancelCampMove"=>"Cancel camp object move","rotateCampLeft"=>"Rotate camp preview left",_=>"Rotate camp preview right"},Arguments=[campTarget],Execute=(i,e)=>{if(WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningCampLayout3D>() is {} camp)switch(name){case "toggleCamp":camp.ToggleEdit();break;case "finishCamp":camp.ExitEdit();break;case "confirmCampMove":camp.ConfirmMove();break;case "cancelCampMove":camp.CancelMove();break;case "rotateCampLeft":camp.RotatePreview(-camp.RotationStep);break;default:camp.RotatePreview(camp.RotationStep);break;}}});
  }
  c.RegisterAction(new(){Id=prefix+"moveCampObject",Category="Mining",MenuGroup="Camp Arrangement",DisplayName="Select camp object to reposition",Arguments=[campTarget,new("object","Camp object",VariableValue.FromString("Self")){IsObjectReference=true}],Execute=(i,e)=>{if(WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningCampLayout3D>() is {} camp&&WeaponEvents.ResolveObject(i,e,"object") is {} o)camp.BeginMove(o.Id);}});
  c.RegisterCondition(new(){Id=prefix+"arrangingCamp",Category="Mining",MenuGroup="Camp Arrangement",DisplayName="Camp arrangement is open",Arguments=[campTarget],Evaluate=(i,e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningCampLayout3D>()?.IsEditing==true});
  A("collectAmmo","Collect produced ammunition",op=>op.GameObject.GetComponent<MiningTrade3D>()?.Collect());
  foreach(string task in new[]{"cycleDefence","cancelDefence","placeDefence"})
  {
   string captured=task;c.RegisterAction(new(){Id=prefix+task,Category="Mining",MenuGroup="Company Defences",DisplayName=task switch{"cycleDefence"=>"Select next available defence","cancelDefence"=>"Cancel defence placement",_=>"Place selected defence at preview"},Arguments=[new("target","Defence planner",VariableValue.FromString("Self")){IsObjectReference=true}],Execute=(i,e)=>{if(WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningDefensePlanner3D>() is {} planner){if(captured=="cycleDefence")planner.CycleBuild();else if(captured=="cancelDefence")planner.Cancel();else if(planner.PlacementValid)planner.TryPlace(planner.PlacementPoint);}}});
  }
  c.RegisterAction(new(){Id=prefix+"playSound",Category="Mining",MenuGroup="Mining Audio",DisplayName="Play mining sound cue",Arguments=[target,new("cue","Sound cue",VariableValue.FromString("Confirm")){Choices=Enum.GetNames<MiningSoundCue>()}],Execute=(i,e)=>{if(WeaponEvents.ResolveObject(i,e) is {} o&&Enum.TryParse<MiningSoundCue>(EventValueResolver.GetString(i,"cue",e,"Confirm"),true,out var cue))MiningAudio3D.Find(o)?.PlayCue(cue,o.Transform.WorldPosition);}});
  MiningBusinessUi3D? Ui(VisualInstruction i,EventExecutionContext e)=>WeaponEvents.ResolveObject(i,e)?.GetComponent<MiningBusinessUi3D>();
  void U(string id,string name,Action<MiningBusinessUi3D> run)=>c.RegisterAction(new(){Id=prefix+id,Category="Mining",MenuGroup="Mining Interface",DisplayName=name,Arguments=[new("target","Mining interface",VariableValue.FromString("Self")){IsObjectReference=true}],Execute=(i,e)=>{if(Ui(i,e) is {} ui)run(ui);}});
  U("openNearby","Interact with nearest mining machine",ui=>ui.OpenNearby());U("closePanel","Close mining panel",ui=>ui.Close());U("openCompany","Open company terminal",ui=>ui.Open(MiningScreen.Company));U("openMarket","Open commodity market",ui=>ui.Open(MiningScreen.Market));U("openAmmo","Open ammo press",ui=>ui.Open(MiningScreen.AmmoPress));U("openRefinery","Open refinery",ui=>ui.Open(MiningScreen.Refinery));U("openDrill","Open drill panel",ui=>ui.Open(MiningScreen.Drill));
  U("primary","Activate current panel main action",ui=>ui.Primary());U("secondary","Activate current panel secondary action",ui=>ui.Secondary());U("less","Decrease sale quantity",ui=>ui.ChangeQuantity(-1));U("more","Increase sale quantity",ui=>ui.ChangeQuantity(1));U("selectRaw","Select raw ore market",ui=>ui.SelectResource(false));U("selectRefined","Select refined ore market",ui=>ui.SelectResource(true));
  for(int index=0;index<5;index++){int choice=index;U("selectDefence"+index,"Select defence placement "+((MiningDefenseKind)index),ui=>ui.SelectDefence(choice));}
  for(int index=0;index<3;index++){int choice=index;U("selectContract"+index,"Select extraction contract "+(index+1),ui=>ui.SelectContract(choice));A("chooseContract"+index,"Choose extraction difficulty "+(index+1),op=>op.SelectContract(choice));}
  for(int row=0;row<3;row++){int r=row;U("buyRow"+r,"Purchase machine upgrade row "+(r+1),ui=>ui.Purchase(r));}
  U("openAudioCredits","Show sound source credits",ui=>ui.Open(MiningScreen.AudioCredits));
  U("openResearch","Open permanent company upgrade map",ui=>ui.Open(MiningScreen.Research));
  U("confirm","Confirm selected company upgrade",ui=>ui.ConfirmSelection());
  for(int node=0;node<128;node++){int n=node;U("selectResearch"+n,"Select company upgrade node "+(n+1),ui=>ui.SelectResearch(n));}
  c.RegisterCondition(new(){Id=prefix+"contractSelected",Category="Mining",MenuGroup="Extraction Contracts",DisplayName="Selected extraction contract is",Arguments=[target,new("contract","Contract ID",VariableValue.FromString("survey")){Choices=["survey","deep","overdrive"]}],Evaluate=(i,e)=>Op(i,e)?.SelectedContractId==EventValueResolver.GetString(i,"contract",e,"survey")});
  c.RegisterCondition(new(){Id=prefix+"cargoFull",Category="Mining",MenuGroup="Mining Business",DisplayName="Cargo hold is full or reserved",Arguments=[target],Evaluate=(i,e)=>Op(i,e)?.CargoFull==true});
  c.RegisterCondition(new(){Id=prefix+"phase",Category="Mining",MenuGroup="Mining Business",DisplayName="Mining operation phase is",Arguments=[target,new("phase","Phase",VariableValue.FromString("Preparation")){Choices=["Preparation","Drilling","Failed"]}],Evaluate=(i,e)=>Op(i,e)?.Phase.ToString().Equals(EventValueResolver.GetString(i,"phase",e,"Preparation"),StringComparison.OrdinalIgnoreCase)==true});
 }
}
